# 方法一：動態規劃（二維）
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)

        # dp[i][j]: s[:i] 是否匹配 p[:j]
        dp = [[False] * (n + 1) for _ in range(m + 1)]

        # 初始化
        dp[0][0] = True  # 空字串匹配空模式

        # 處理前導 '*'
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[0][j] = dp[0][j - 1]

        # 填表
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if p[j - 1] == '*':
                    # '*' 匹配空序列 或 匹配一個或多個字符
                    dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
                elif p[j - 1] == '?' or s[i - 1] == p[j - 1]:
                    # 字符匹配
                    dp[i][j] = dp[i - 1][j - 1]

        return dp[m][n]


# 方法二：動態規劃（空間優化）
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)

        # 只需要兩行：當前行和上一行
        prev = [False] * (n + 1)
        prev[0] = True

        # 處理前導 '*'
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                prev[j] = prev[j - 1]

        # 逐行更新
        for i in range(1, m + 1):
            curr = [False] * (n + 1)
            for j in range(1, n + 1):
                if p[j - 1] == '*':
                    curr[j] = curr[j - 1] or prev[j]
                elif p[j - 1] == '?' or s[i - 1] == p[j - 1]:
                    curr[j] = prev[j - 1]
            prev = curr

        return prev[n]


# 方法三：貪心 + 回溯（最優）
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        sIndex = pIndex = 0
        starIndex = match = -1

        while sIndex < len(s):
            # 情況 1：字符匹配或 '?'
            if pIndex < len(p) and (p[pIndex] == '?' or s[sIndex] == p[pIndex]):
                sIndex += 1
                pIndex += 1

            # 情況 2：遇到 '*'，記錄位置
            elif pIndex < len(p) and p[pIndex] == '*':
                starIndex = pIndex
                match = sIndex
                pIndex += 1  # '*' 先匹配空序列

            # 情況 3：回溯，讓 '*' 多匹配一個字符
            elif starIndex != -1:
                pIndex = starIndex + 1
                match += 1
                sIndex = match

            # 情況 4：匹配失敗
            else:
                return False

        # 處理 p 中剩餘的 '*'
        while pIndex < len(p) and p[pIndex] == '*':
            pIndex += 1

        return pIndex == len(p)


# 方法四：遞迴 + 記憶化
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        memo = {}

        def dp(i, j):
            # 已經計算過
            if (i, j) in memo:
                return memo[(i, j)]

            # 兩個都到達末尾
            if i == len(s) and j == len(p):
                return True

            # p 到達末尾，s 還有剩餘
            if j == len(p):
                return False

            # s 到達末尾，檢查 p 剩餘是否都是 '*'
            if i == len(s):
                result = all(c == '*' for c in p[j:])
                memo[(i, j)] = result
                return result

            # 字符匹配或 '?'
            if p[j] == '?' or s[i] == p[j]:
                result = dp(i + 1, j + 1)
            # '*'
            elif p[j] == '*':
                # '*' 匹配空序列 或 匹配一個或多個字符
                result = dp(i, j + 1) or dp(i + 1, j)
            else:
                result = False

            memo[(i, j)] = result
            return result

        return dp(0, 0)

