public:
    bool isMatch(string s, string p) {
        int sIndex = 0, pIndex = 0;
        int starIndex = -1, match = -1;

        while (sIndex < s.length()) {
            if (pIndex < p.length() && 
                (p[pIndex] == '?' || s[sIndex] == p[pIndex])) {
                sIndex++;
                pIndex++;
            }
            else if (pIndex < p.length() && p[pIndex] == '*') {
                starIndex = pIndex;
                match = sIndex;
                pIndex++;
            }
            else if (starIndex != -1) {
                pIndex = starIndex + 1;
                match++;
                sIndex = match;
            }
